from math import sqrt
import numpy as np

def bm_moment(k, t):
    if k % 2 == 1:
        return 0.0
    dfact = 1
    for j in range(k - 1, 0, -2):
        dfact *= j
    return dfact * t ** (k / 2)

def isometry_var(f, T, n=10000):
    dt = T / n
    return sum(f((i + 0.5) * dt) ** 2 for i in range(n)) * dt

def mc_moment(k, t, paths, seed):
    W = sqrt(t) * np.random.default_rng(seed).standard_normal(paths)
    v = W ** k
    return [float(v.mean()), float(v.std(ddof=1) / sqrt(paths))]
